From 91ab17e2fe57d5c093f9a2c63342e58df6cf024b Mon Sep 17 00:00:00 2001
From: Lynne <dev@lynne.ee>
Date: Wed, 5 Jun 2024 18:31:52 +0200
Subject: [PATCH] aacdec_usac: tag LFE channels as such in the channel map

Missed.
---
 libavcodec/aac/aacdec_usac.c | 3 +++
 1 file changed, 3 insertions(+)

diff --git a/libavcodec/aac/aacdec_usac.c b/libavcodec/aac/aacdec_usac.c
index 3a573ab..b12eda9 100644
--- a/libavcodec/aac/aacdec_usac.c
+++ b/libavcodec/aac/aacdec_usac.c
@@ -447,6 +447,9 @@ int ff_aac_usac_config_decode(AACDecContext *ac, AVCodecContext *avctx,
             /* LFE has no need for any configuration */
             e->tw_mdct = 0;
             e->noise_fill = 0;
+            layout_map[i][0] = TYPE_LFE;
+            layout_map[i][1] = i;
+            layout_map[i][2] = AAC_CHANNEL_LFE;
             elem_id[2]++;
             break;
         case ID_USAC_EXT: /* EXT */
